-- V30.69.44. Additive only. No historical financial or inventory inference.
CREATE TABLE IF NOT EXISTS pink_receiving_sources(business_unit_id INTEGER NOT NULL REFERENCES business_units(id),source_type TEXT NOT NULL CHECK(source_type IN ('import','packaging')),source_id INTEGER NOT NULL,baseline_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(business_unit_id,source_type,source_id));
CREATE TABLE IF NOT EXISTS pink_receiving_receipts(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL REFERENCES business_units(id),source_type TEXT NOT NULL CHECK(source_type IN ('import','packaging')),source_id INTEGER NOT NULL,supplier_id INTEGER NOT NULL REFERENCES pink_salt_suppliers(id),receipt_no TEXT NOT NULL UNIQUE,receipt_date TEXT NOT NULL,location_id INTEGER NOT NULL REFERENCES pink_salt_storage_locations(id),reference TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',evidence_json TEXT NOT NULL DEFAULT '[]',replacement_id INTEGER REFERENCES pink_receiving_settlements(id),legacy_id INTEGER REFERENCES pink_pack_receipts(id),journal_id INTEGER REFERENCES accounting_journal_entries(id),created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS pink_receiving_source_receipts ON pink_receiving_receipts(business_unit_id,source_type,source_id,id);
CREATE TABLE IF NOT EXISTS pink_receiving_lines(id INTEGER PRIMARY KEY,receipt_id INTEGER NOT NULL REFERENCES pink_receiving_receipts(id),source_line_id INTEGER NOT NULL,snapshot_json TEXT NOT NULL,expected_q INTEGER NOT NULL CHECK(expected_q>=0),physical_q INTEGER NOT NULL CHECK(physical_q>=0),fulfillment_q INTEGER NOT NULL CHECK(fulfillment_q>=0),accepted_q INTEGER NOT NULL CHECK(accepted_q>=0),quarantine_q INTEGER NOT NULL CHECK(quarantine_q>=0),rejected_q INTEGER NOT NULL CHECK(rejected_q>=0),expected_bags INTEGER CHECK(expected_bags>=0),actual_bags INTEGER CHECK(actual_bags>=0),quality TEXT NOT NULL,remarks TEXT NOT NULL DEFAULT '',discrepancies_json TEXT NOT NULL DEFAULT '[]',legacy_id INTEGER REFERENCES pink_pack_receipt_lines(id),CHECK(physical_q=accepted_q+quarantine_q+rejected_q),UNIQUE(receipt_id,source_line_id));
CREATE TABLE IF NOT EXISTS pink_receiving_events(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL REFERENCES business_units(id),line_id INTEGER NOT NULL REFERENCES pink_receiving_lines(id),from_state TEXT NOT NULL,to_state TEXT NOT NULL,quantity_q INTEGER NOT NULL CHECK(quantity_q>0),action TEXT NOT NULL,reason TEXT NOT NULL,movement_date TEXT NOT NULL,raw_movement_id INTEGER REFERENCES pink_salt_raw_stock_movements(id),pack_movement_id INTEGER REFERENCES pink_salt_packaging_movements(id),journal_id INTEGER REFERENCES accounting_journal_entries(id),settlement_id INTEGER REFERENCES pink_receiving_settlements(id),created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS pink_receiving_events_line ON pink_receiving_events(line_id,id);
CREATE TABLE IF NOT EXISTS pink_receiving_cases(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL REFERENCES business_units(id),supplier_id INTEGER NOT NULL REFERENCES pink_salt_suppliers(id),source_type TEXT NOT NULL,source_id INTEGER NOT NULL,source_line_id INTEGER NOT NULL,line_id INTEGER REFERENCES pink_receiving_lines(id),case_no TEXT NOT NULL UNIQUE,title TEXT NOT NULL,dimension TEXT NOT NULL CHECK(dimension IN ('stock','bags')),quantity_q INTEGER NOT NULL CHECK(quantity_q>=0),currency TEXT NOT NULL,claim_cents INTEGER NOT NULL DEFAULT 0 CHECK(claim_cents>=0),recognition_rate TEXT,status TEXT NOT NULL DEFAULT 'Open',revision INTEGER NOT NULL DEFAULT 1,agreed_revision INTEGER,parties_json TEXT NOT NULL DEFAULT '[]',resolution_json TEXT NOT NULL DEFAULT '{}',evidence_json TEXT NOT NULL DEFAULT '[]',notes TEXT NOT NULL DEFAULT '',supplier_response TEXT NOT NULL DEFAULT '',assigned_to INTEGER REFERENCES users(id),follow_up TEXT,parent_id INTEGER REFERENCES pink_receiving_cases(id),approval_id INTEGER REFERENCES approvals(id),created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS pink_receiving_supplier_cases ON pink_receiving_cases(business_unit_id,supplier_id,status,id);
CREATE TABLE IF NOT EXISTS pink_receiving_settlements(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL REFERENCES business_units(id),case_id INTEGER NOT NULL REFERENCES pink_receiving_cases(id),case_revision INTEGER NOT NULL,party TEXT NOT NULL CHECK(party IN ('Supplier','Company','Carrier / Insurer')),counterparty TEXT NOT NULL DEFAULT '',method TEXT NOT NULL CHECK(method IN ('Later Delivery','Replacement','Invoice Reduction','Purchase Credit','Cash Refund','Company Loss')),currency TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),quantity_q INTEGER NOT NULL DEFAULT 0 CHECK(quantity_q>=0),recognition_rate TEXT NOT NULL,due_date TEXT,snapshot_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'Agreed',journal_id INTEGER REFERENCES accounting_journal_entries(id),created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pink_receiving_allocations(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL REFERENCES business_units(id),settlement_id INTEGER NOT NULL REFERENCES pink_receiving_settlements(id),source_type TEXT NOT NULL,source_id INTEGER NOT NULL,source_currency TEXT NOT NULL,source_cents INTEGER NOT NULL CHECK(source_cents>0),target_currency TEXT NOT NULL,target_cents INTEGER NOT NULL CHECK(target_cents>0),carrying_krw_cents INTEGER NOT NULL,target_krw_cents INTEGER NOT NULL,allocation_date TEXT NOT NULL,quote_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'Active',journal_id INTEGER REFERENCES accounting_journal_entries(id),created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS pink_receiving_target_allocations ON pink_receiving_allocations(business_unit_id,source_type,source_id,status);
CREATE TABLE IF NOT EXISTS pink_receiving_refunds(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL REFERENCES business_units(id),settlement_id INTEGER NOT NULL REFERENCES pink_receiving_settlements(id),refund_date TEXT NOT NULL,settled_cents INTEGER NOT NULL CHECK(settled_cents>0),currency TEXT NOT NULL,received_cents INTEGER NOT NULL CHECK(received_cents>0),valuation_rate TEXT NOT NULL,payment_account_id INTEGER NOT NULL REFERENCES accounting_payment_accounts(id),reference TEXT NOT NULL,evidence_file TEXT NOT NULL,proposal_json TEXT NOT NULL,quote_json TEXT NOT NULL DEFAULT '{}',finance_entry_id INTEGER REFERENCES finance_entries(id),status TEXT NOT NULL DEFAULT 'Active',created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS pink_receiving_refund_reference ON pink_receiving_refunds(payment_account_id,lower(trim(reference))) WHERE status='Active';
CREATE TABLE IF NOT EXISTS pink_receiving_actions(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL REFERENCES business_units(id),kind TEXT NOT NULL,entity_id INTEGER NOT NULL,body_json TEXT NOT NULL,fingerprint TEXT NOT NULL,approval_id INTEGER REFERENCES approvals(id),status TEXT NOT NULL DEFAULT 'Pending',result_json TEXT,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pink_receiving_policy(business_unit_id INTEGER PRIMARY KEY REFERENCES business_units(id),revision INTEGER NOT NULL DEFAULT 1,policy_json TEXT NOT NULL,reason TEXT NOT NULL,approved_by INTEGER NOT NULL REFERENCES users(id),approved_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pink_receiving_history(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL REFERENCES business_units(id),entity_type TEXT NOT NULL,entity_id INTEGER NOT NULL,action TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,reason TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS pink_receiving_history_entity ON pink_receiving_history(business_unit_id,entity_type,entity_id,id);
CREATE TABLE IF NOT EXISTS pink_receiving_closures(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL REFERENCES business_units(id),source_type TEXT NOT NULL,source_id INTEGER NOT NULL,source_line_id INTEGER NOT NULL,case_id INTEGER NOT NULL UNIQUE REFERENCES pink_receiving_cases(id),quantity_q INTEGER NOT NULL CHECK(quantity_q>0),status TEXT NOT NULL DEFAULT 'Active',reason TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS pink_receiving_payment_credits(transaction_id INTEGER NOT NULL REFERENCES pink_fx_transactions(id),allocation_id INTEGER NOT NULL UNIQUE REFERENCES pink_receiving_allocations(id),PRIMARY KEY(transaction_id,allocation_id));
CREATE TABLE IF NOT EXISTS pink_receiving_migrations(version TEXT PRIMARY KEY,baseline_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pink_receiving_charges(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL REFERENCES business_units(id),case_id INTEGER NOT NULL REFERENCES pink_receiving_cases(id),case_revision INTEGER NOT NULL,source_type TEXT NOT NULL,source_id INTEGER NOT NULL,currency TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),amount_krw_cents INTEGER NOT NULL CHECK(amount_krw_cents>=0),quantity_q INTEGER NOT NULL CHECK(quantity_q>0),unit_cost_krw REAL NOT NULL CHECK(unit_cost_krw>=0),treatment TEXT NOT NULL CHECK(treatment IN ('No Charge','Additional Payable')),status TEXT NOT NULL DEFAULT 'Active',journal_id INTEGER REFERENCES accounting_journal_entries(id),created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(case_id,case_revision));
